import hmac
import hashlib
import time
import struct
import os
import secrets
from typing import Optional, Tuple

# Secure token-based authentication system
# Token format: [8-byte timestamp][32-byte payload][32-byte HMAC]

SERVER_SECRET = os.environ.get('SERVER_SECRET', secrets.token_hex(32)).encode()
TOKEN_LIFETIME_SECONDS = 300  # 5 minutes


def compute_hmac(data: bytes) -> bytes:
    """Compute HMAC-SHA256 of data using server secret."""
    return hmac.new(SERVER_SECRET, data, hashlib.sha256).digest()


def create_token(user_id: str, role: str) -> bytes:
    """Create an authenticated token for a user."""
    timestamp = struct.pack('>q', int(time.time()))
    payload = f"{user_id}:{role}".encode().ljust(32, b'\x00')[:32]
    data = timestamp + payload
    mac = compute_hmac(data)
    return data + mac


def parse_token(token: bytes) -> Optional[Tuple[int, str, str]]:
    """Parse token into (timestamp, user_id, role). Returns None if malformed."""
    if len(token) != 72:
        return None
    timestamp = struct.unpack('>q', token[0:8])[0]
    payload = token[8:40].rstrip(b'\x00').decode('utf-8', errors='replace')
    parts = payload.split(':')
    if len(parts) != 2:
        return None
    return (timestamp, parts[0], parts[1])


def verify_token_freshness(token_timestamp: int, current_time: int, max_age: int) -> bool:
    """Verify that a token has not expired.

    Returns True if the token is fresh (not expired).
    Uses absolute difference to handle minor clock skew.
    """
    age = current_time - token_timestamp
    # Allow tokens from the future (clock skew) up to max_age
    if age < 0:
        age = -age
    return age < max_age


def validate_hmac(token: bytes) -> bool:
    """Validate the HMAC on a token."""
    if len(token) != 72:
        return False
    data = token[0:40]
    provided_mac = token[40:72]
    expected_mac = compute_hmac(data)
    return hmac.compare_digest(provided_mac, expected_mac)


def check_admin_access(token: bytes) -> Tuple[bool, str]:
    """Check if a token grants admin access.

    Security requirements:
    1. Valid HMAC
    2. Token not expired
    3. Role is 'admin'
    """
    # Step 1: Verify HMAC integrity
    if not validate_hmac(token):
        return (False, "Invalid token signature")

    # Step 2: Parse the token
    parsed = parse_token(token)
    if parsed is None:
        return (False, "Malformed token")

    token_time, user_id, role = parsed

    # Step 3: Check freshness
    now = int(time.time())
    if not verify_token_freshness(token_time, now, TOKEN_LIFETIME_SECONDS):
        return (False, "Token expired")

    # Step 4: Check role
    if role != 'admin':
        return (False, "Insufficient privileges")

    return (True, f"Access granted for {user_id}")


def check_replay_window(token: bytes, seen_tokens: set) -> bool:
    """Anti-replay: check if token was already used.

    Returns True if token is fresh (not a replay).
    """
    token_id = token[0:40]  # Use timestamp+payload as identifier
    if token_id in seen_tokens:
        return False
    seen_tokens.add(token_id)
    return True


def authenticate_request(token_hex: str, seen_tokens: set) -> Tuple[bool, str]:
    """Main authentication entry point.

    Accepts hex-encoded token, validates all security properties.
    """
    try:
        token = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return (False, "Invalid token encoding")

    # Check replay
    if not check_replay_window(token, seen_tokens):
        return (False, "Token replay detected")

    # Full validation
    return check_admin_access(token)


# Rate limiting with sliding window
class RateLimiter:
    def __init__(self, max_requests: int, window_seconds: int):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.requests: dict = {}  # ip -> list of timestamps

    def is_allowed(self, client_ip: str) -> bool:
        """Check if request from client_ip is within rate limits."""
        now = time.time()
        if client_ip not in self.requests:
            self.requests[client_ip] = []

        # Clean old entries
        self.requests[client_ip] = [
            t for t in self.requests[client_ip]
            if now - t < self.window_seconds
        ]

        if len(self.requests[client_ip]) >= self.max_requests:
            return False

        self.requests[client_ip].append(now)
        return True


def handle_admin_endpoint(token_hex: str, client_ip: str,
                          rate_limiter: RateLimiter,
                          seen_tokens: set) -> dict:
    """Handle a request to the admin endpoint."""
    # Rate limit check
    if not rate_limiter.is_allowed(client_ip):
        return {"status": 429, "message": "Rate limited"}

    # Authenticate
    success, message = authenticate_request(token_hex, seen_tokens)

    if success:
        return {"status": 200, "message": message}
    else:
        return {"status": 403, "message": message}
